"name": "20260127040121_4c8556b6-9c18-4da9-98b1-f4de5a1f7555.sql",
"sql": "-- Add 'employer' role to app_role enum\nALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'employer';"
